APP_ICON_PNG_BASE64 = """"""


def resource_path(relative_path):
    try:
        base_path = sys._MEIPASS
    except Exception:
        base_path = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base_path, relative_path)


def apply_app_icon(window):
    """Устанавливает иконку окна.
    Сначала пробует внешний ICO/PNG рядом с программой или в PyInstaller bundle,
    затем использует встроенную PNG-иконку как резервный вариант.
    """
    # внешний .ico удобен для Windows titlebar/taskbar
    for icon_name in ('neuron_astro_stage45_icon.ico', 'neuron_astro_app_icon.ico', 'icon.ico'):
        try:
            icon_path = resource_path(icon_name)
            if os.path.exists(icon_path):
                window.iconbitmap(icon_path)
                return True
        except Exception:
            pass

    # резервный встроенный PNG, чтобы иконка была даже без внешнего файла
    try:
        icon_image = PhotoImage(data=APP_ICON_PNG_BASE64)
        window.iconphoto(True, icon_image)
        window._app_icon_ref = icon_image
        return True
    except Exception:
        return False



def upload_date():
  # Если файл начальных условий отсутствует или повреждён, используем безопасные значения по умолчанию.
  for path in (PERSISTENT_INITIAL_CONDITIONS_FILE, 'initial_conditions.txt'):
    try:
      vv, mm, nn, hh = _read_float_lines(path, 4)
      return vv, mm, nn, hh
    except Exception as error:
      log_nonfatal_error(f'Не удалось прочитать начальные условия из {path}', error)
  return -60.0, 0.09, 0.0009, 0.3

