def make_run_label(kind, params='', method=''):
  """Формирует подпись запуска для истории и окон сравнения.

  В stage45 эта функция случайно отсутствовала, из-за чего после численного
  расчёта падал этап отрисовки графиков для вкладок «Два нейрона» и
  «Астроцит».
  """
  parts = []
  if kind:
    parts.append(str(kind))
  if params:
    parts.append(str(params))
  if method:
    parts.append(str(method))
  return '; '.join(parts) if parts else 'Расчёт'





def integrate_date(vv = -60, mm = 0.09, nn = 0.0009, hh = 0.3, z = 10000000, q = 0.000001, iapp = 0.0, method = None, save_initial = True):
  method = 2 if method is None else method
  if method == 1:
    Box = EULER(z, q, vv, mm, nn, hh, iapp)
  elif method == 2:
    Box = RK4(z, q, vv, mm, nn, hh, iapp)
  elif method in (3, 4):
    Box = solve_ivp_single(z, q, vv, mm, nn, hh, iapp, method)
  else:
    Box = RK4(z, q, vv, mm, nn, hh, iapp)

  if save_initial:
    load_date(Box)
  return Box


def integrate_date1(z = 100000, q = 0.0001, iapp_1 = 0.0, iapp_2 = 0.0, gsyn = 0.1, Esyn = 0, u4 = 0.5, gastro = 2.0, method = None, save_initial = True):
  vv, mm, nn, hh = upload_date()
  method = 2 if method is None else method

  if method == 1:
    Box1, Box2, Box3, Box4 = EULER1(z, q, vv, mm, nn, hh, iapp_1, iapp_2, gsyn, Esyn, u4, gastro)
  elif method == 2:
    Box1, Box2, Box3, Box4 = RK41(z, q, vv, mm, nn, hh, iapp_1, iapp_2, gsyn, Esyn, u4, gastro)
  elif method in (3, 4):
    Box1, Box2, Box3, Box4 = solve_ivp_ensemble(z, q, vv, mm, nn, hh, iapp_1, iapp_2, gsyn, Esyn, u4, gastro, method)
  else:
    Box1, Box2, Box3, Box4 = RK41(z, q, vv, mm, nn, hh, iapp_1, iapp_2, gsyn, Esyn, u4, gastro)

  if save_initial:
    load_date(Box1)
  return Box1, Box2, Box3, Box4
  

