def refresh_graph_layout_metrics():
  """Пересчитывает ширину графиков под текущее окно для следующих построений."""
  global GRAPH_RIGHT_X, GRAPH_W, BIG_GRAPH_W, WIDE_GRAPH_W
  try:
    root_obj = globals().get('root')
    window_w = int(root_obj.winfo_width()) if root_obj is not None else 1920
    if window_w < 900:
      window_w = 1920
    available = max(900, window_w - GRAPH_AREA_X - 55)
    GRAPH_W = max(430, int((available - 34) / 2))
    GRAPH_RIGHT_X = GRAPH_LEFT_X + GRAPH_W + 34
    BIG_GRAPH_W = available
    WIDE_GRAPH_W = available
  except Exception:
    pass


