def data_cropping(Box, fraction=TRANSIENT_FRACTION):
  """Отбрасывает начальный переходный участок траектории.

  По умолчанию удаляются первые 25% рассчитанных точек. Это поведение явно
  используется перед анализом частот, фазовыми портретами и основными графиками,
  чтобы отображалась установившаяся динамика, а не начальный переходный процесс.
  """
  arr = np.asarray(Box)
  if arr.ndim != 2 or arr.shape[1] == 0:
    return arr
  start = int(fraction * arr.shape[1])
  if start >= arr.shape[1]:
    start = max(0, arr.shape[1] - 1)
  return arr[:, start:]


def downsample_box(Box, max_points=20000):
  arr = np.asarray(Box)
  if arr.shape[1] <= max_points:
    return arr
  index = np.linspace(0, arr.shape[1] - 1, max_points).astype(int)
  return arr[:, index]


def crop_time_window(Box, t_min=None, t_max=None):
  """Возвращает участок траектории по времени без изменения численного расчёта."""
  arr = np.asarray(Box)
  if arr.shape[1] == 0:
    return arr
  mask = np.ones(arr.shape[1], dtype=bool)
  if t_min is not None:
    mask &= arr[0] >= t_min
  if t_max is not None:
    mask &= arr[0] <= t_max
  result = arr[:, mask]
  if result.shape[1] == 0:
    return arr[:, :1]
  return result


def crop_after_transient_window(Box, window_seconds=PLOT_WINDOW_SECONDS):
  """Берёт первые window_seconds после удаления первых 25% траектории.

  Это важно для графиков с прежней шириной окна 1 секунда: теперь окно начинается
  не с t=0, а после переходного участка, например с t=7.5 при расчёте 30 секунд.
  """
  cropped = data_cropping(Box)
  if cropped.shape[1] == 0:
    return cropped
  t_start = cropped[0, 0]
  t_end = t_start + window_seconds
  return crop_time_window(cropped, t_start, t_end)


def get_xlim_for_box(Box):
  arr = np.asarray(Box)
  if arr.shape[1] == 0:
    return 0.0, PLOT_WINDOW_SECONDS
  return float(arr[0, 0]), float(arr[0, -1])




def get_xlim_for_frequency_cells(*cells, fallback_box=None):
  """Подбирает диапазон X для графика частоты."""
  times = []
  for cell in cells:
    try:
      if cell is None or len(cell) < 1:
        continue
      arr = np.asarray(cell[0], dtype=float)
      arr = arr[np.isfinite(arr)]
      if arr.size:
        times.extend(arr.tolist())
    except Exception:
      pass

  if times:
    x0 = float(min(times))
    x1 = float(max(times))
    if x1 <= x0:
      x1 = x0 + 1.0
    pad = max(0.05, 0.03 * (x1 - x0))
    return x0 - pad, x1 + pad

  if fallback_box is not None:
    try:
      return get_xlim_for_box(fallback_box)
    except Exception:
      pass

  return 0.0, 1.0


def mean_frequency_from_cell(cell):
  try:
    values = np.asarray(cell[1], dtype=float)
    values = values[np.isfinite(values)]
    if values.size == 0:
      return None
    return float(np.mean(values))
  except Exception:
    return None


def format_frequency_value(value):
  if value is None:
    return '—'
  try:
    return f'{float(value):.4g}'
  except Exception:
    return '—'


