def _ensure_persistent_dirs():
  os.makedirs(PERSISTENT_STATE_DIR, exist_ok=True)
  os.makedirs(PERSISTENT_RUNS_DIR, exist_ok=True)


def log_nonfatal_error(context, error=None):
  """Пишет нефатальную ошибку в журнал, если журнал уже создан."""
  try:
    details = f': {error}' if error is not None else ''
    append_log(f'{context}{details}')
  except Exception:
    pass


def _read_float_lines(path, expected_count):
  with open(path, 'r', encoding='utf-8') as file:
    data = [float(line.strip()) for line in file if line.strip()]
  if len(data) < expected_count:
    raise ValueError(f'Недостаточно значений в {path}')
  return data[:expected_count]


def _write_float_lines(path, values):
  _ensure_persistent_dirs()
  with open(path, 'w', encoding='utf-8') as file:
    file.write('\n'.join(str(float(value)) for value in values))


def resolve_history_tab_key(record):
  """Возвращает внутренний ключ вкладки по записи истории."""
  tab_title = str(record.get('tab_title', ''))
  for key, title in TAB_TITLES.items():
    if title == tab_title:
      return key
  return str(record.get('tab_key', ''))


def _make_safe_filename(text):
  try:
    text = str(text)
  except Exception:
    text = 'run'
  allowed = []
  for ch in text:
    if ch.isalnum() or ch in ('-', '_'):
      allowed.append(ch)
    elif ch in (' ', '.', ':', ';', ',', '=', '(', ')'):
      allowed.append('_')
  result = ''.join(allowed).strip('_')
  while '__' in result:
    result = result.replace('__', '_')
  return result[:80] or 'run'


