def get_dataset_point_summary(dataset):
  kind = str(dataset.get('kind', ''))
  try:
    if kind == 'single':
      return f"V(t): {len(np.asarray(dataset.get('t', [])))} точек; частота: {len(np.asarray(dataset.get('freq_t', [])))} точек"
    if kind == 'freq':
      return f"Iapp: {len(np.asarray(dataset.get('T', [])))} точек"
    if kind == 'pair':
      return f"V(t): {len(np.asarray(dataset.get('t_v', [])))} точек; частоты: {len(np.asarray(dataset.get('freq_t1', [])))} / {len(np.asarray(dataset.get('freq_t2', [])))}"
    if kind in ('sync_map', 'sync_time'):
      x = np.asarray(dataset.get('x', []))
      y = np.asarray(dataset.get('y', []))
      return f"карта: {len(x)} x {len(y)}"
    if kind == 'astro':
      return f"Ca(t): {len(np.asarray(dataset.get('t_ca', [])))} точек; частоты: {len(np.asarray(dataset.get('freq_t1', [])))} / {len(np.asarray(dataset.get('freq_t2', [])))}"
  except Exception:
    pass
  return 'состав данных не распознан'


def validate_calculation_dataset(dataset):
  warnings = []
  meta = dataset.get('meta', {}) or {}
  file_format = str(meta.get('file_format', ''))
  file_version = int(meta.get('file_version', 0) or 0)
  kind = str(dataset.get('kind', '') or meta.get('kind', ''))

  if file_format and file_format != CALCULATION_TEXT_FORMAT:
    warnings.append('формат файла отличается от текущего формата программы')
  if file_version and file_version < CALCULATION_TEXT_VERSION:
    warnings.append(f'файл создан в старой версии формата ({file_version}), текущая версия: {CALCULATION_TEXT_VERSION}')
  if not file_version:
    warnings.append('у файла нет версии схемы, это может быть старый NPZ или старый TXT')

  required = {
      'single': ('t', 'v', 'm', 'n', 'h'),
      'freq': ('T', 'forward'),
      'pair': ('t_v', 'v1', 'v2'),
      'sync_map': ('x', 'y', 'values'),
      'sync_time': ('x', 'y', 'values'),
      'astro': ('t_ca', 'ca'),
  }.get(kind, ())
  missing = [name for name in required if name not in dataset or np.asarray(dataset.get(name)).size == 0]
  if missing:
    warnings.append('не хватает данных для графиков: ' + ', '.join(missing))
  return warnings


def confirm_calculation_file_load(path, record, dataset):
  meta = dataset.get('meta', {}) or {}
  warnings = validate_calculation_dataset(dataset)
  lines = [
      f"Файл: {os.path.basename(path)}",
      f"Вкладка: {record.get('tab_title', '-')}",
      f"Расчёт: {record.get('title', '-')}",
      f"Метод: {record.get('method', '-') or '-'}",
      f"Создан: {meta.get('created_at') or record.get('time', '-')}",
      f"Данные: {get_dataset_point_summary(dataset)}",
  ]
  if warnings:
    lines.append('')
    lines.append('Предупреждения:')
    lines.extend('- ' + item for item in warnings)
  lines.append('')
  lines.append('Построить графики из этого файла?')
  return askyesno('Открытие расчёта', '\n'.join(lines))


def save_current_calculation_to_file(frame=None):
  key = str(frame) if frame is not None else get_current_ui_key()
  record, dataset = build_current_calculation_dataset(key, frame=frame)
  if not dataset:
    showinfo('Сохранение расчёта', 'На выбранной вкладке пока нет завершённого расчёта для сохранения.')
    return

  tab_title = record.get('tab_title', 'Расчёт')
  default_name = _make_safe_filename(f'{tab_title}_{datetime.now().strftime("%Y%m%d_%H%M%S")}')
  path = asksaveasfilename(
      title='Сохранить расчёт',
      defaultextension='.txt',
      filetypes=[('Текстовый файл расчёта', '*.txt'), ('Файл расчёта NumPy', '*.npz')],
      initialfile=default_name,
  )
  if not path:
    return

  try:
    write_calculation_dataset(path, dataset, record)
    add_recent_calculation_file(path)
    update_source_badge(str(frame or notebook.nametowidget(notebook.select())), f'Сохранён: {os.path.basename(path)}', mode='current')
    append_log(f'Расчёт сохранён в файл: {path}')
    showinfo('Сохранение расчёта', 'Расчёт сохранён в файл.')
  except Exception as error:
    showerror('Сохранение расчёта', f'Не удалось сохранить расчёт:\n{error}')


def open_calculation_file_for_plot(frame=None, path=None):
  if path is None:
    path = askopenfilename(
        title='Выберите файл расчёта',
        filetypes=[('Текстовый файл расчёта', '*.txt'), ('Файл расчёта NumPy', '*.npz'), ('Все файлы', '*.*')],
    )
  if not path:
    return

  try:
    dataset = load_calculation_dataset_from_file(path)
    kind = str(dataset.get('kind', '') or dataset.get('meta', {}).get('kind', '')).strip()
    record = _make_record_for_dataset(kind=kind, meta=dataset.get('meta', {}), path=path)
    if not confirm_calculation_file_load(path, record, dataset):
      append_log(f'Открытие расчёта отменено: {path}')
      return
    show_loaded_history_dataset(record, dataset)
    add_recent_calculation_file(path)
    append_log(f'Открыт расчёт из файла: {path}')
  except Exception as error:
    showerror('Открытие расчёта', f'Не удалось открыть файл расчёта:\n{error}')


