def delete_selected_history_record():
  record = get_selected_history_record()
  if not record:
    showinfo('История расчётов', 'Выберите запуск, который нужно удалить.')
    return
  delete_history_record_dataset(record)
  try:
    record_id = int(record.get('id', 0))
  except Exception:
    record_id = 0
  new_records = []
  for item in HISTORY_RECORDS:
    try:
      if int(item.get('id', 0)) == record_id:
        continue
    except Exception:
      pass
    new_records.append(item)
  HISTORY_RECORDS[:] = new_records
  refresh_history_tree_from_records()
  save_persistent_state()
  append_log(f'Из истории удалён запуск №{record_id}.')



def _jsonable(value):
  """Преобразует numpy-объекты в обычные типы JSON."""
  try:
    if isinstance(value, np.ndarray):
      return value.tolist()
    if isinstance(value, (np.integer, np.floating, np.bool_)):
      return value.item()
    if isinstance(value, dict):
      return {str(key): _jsonable(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
      return [_jsonable(item) for item in value]
  except Exception:
    pass
  return value


def _float_array(value):
  """Безопасно восстанавливает массив float из JSON."""
  try:
    if value is None:
      return np.array([], dtype=float)
    return np.asarray(value, dtype=float)
  except Exception:
    return np.array([], dtype=float)


def _tab_code_from_key(key):
  """Стабильный код вкладки, который не зависит от внутренних имён Tkinter."""
  try:
    mapping = {
        str(frame1): 'single',
        str(frame2): 'freq',
        str(frame3): 'pair',
        str(frame4): 'sync_map',
        str(frame5): 'sync_time',
        str(frame6): 'astro',
    }
    return mapping.get(key, '')
  except Exception:
    return ''


def _tab_key_from_code(code):
  """Возвращает текущий ключ Tkinter по стабильному коду вкладки."""
  try:
    mapping = {
        'single': str(frame1),
        'freq': str(frame2),
        'pair': str(frame3),
        'sync_map': str(frame4),
        'sync_time': str(frame5),
        'astro': str(frame6),
    }
    return mapping.get(code)
  except Exception:
    return None


def resolve_history_tab_key(record):
  """Находит актуальный ключ вкладки для записи истории после перезапуска программы."""
  try:
    code = record.get('tab_code')
    key_from_code = _tab_key_from_code(code)
    if key_from_code:
      return key_from_code

    key = record.get('tab_key')
    if key in TAB_TITLES:
      return key

    title = record.get('tab_title')
    for current_key, current_title in TAB_TITLES.items():
      if current_title == title:
        return current_key
  except Exception:
    pass
  return record.get('tab_key')


def _serialize_single_compare_run(run):
  return {
      't': _jsonable(run.get('t', [])),
      'v': _jsonable(run.get('v', [])),
      'freq_t': _jsonable(run.get('freq_t', [])),
      'freq': _jsonable(run.get('freq', [])),
      'label': str(run.get('label', 'запуск')),
      'params': str(run.get('params', '')),
      'enabled': bool(run.get('enabled', True)),
  }


def _serialize_freq_compare_run(run):
  return {
      'T': _jsonable(run.get('T', [])),
      'forward': _jsonable(run.get('forward', [])),
      'backward_plot': _jsonable(run.get('backward_plot', [])),
      'label': str(run.get('label', 'запуск')),
      'params': str(run.get('params', '')),
      'enabled': bool(run.get('enabled', True)),
  }


def _restore_single_compare_runs(items):
  restored = []
  for item in items or []:
    try:
      t = _float_array(item.get('t'))
      v = _float_array(item.get('v'))
      if t.size == 0 or v.size == 0:
        continue
      restored.append({
          't': t,
          'v': v,
          'freq_t': _float_array(item.get('freq_t')),
          'freq': _float_array(item.get('freq')),
          'label': str(item.get('label', f'запуск {len(restored) + 1}')),
          'params': str(item.get('params', '')),
          'enabled': bool(item.get('enabled', True)),
      })
    except Exception:
      continue
  return restored[-8:]


def _restore_freq_compare_runs(items):
  restored = []
  for item in items or []:
    try:
      T = _float_array(item.get('T'))
      forward = _float_array(item.get('forward'))
      backward = _float_array(item.get('backward_plot'))
      if T.size == 0 or forward.size == 0 or backward.size == 0:
        continue
      restored.append({
          'T': T,
          'forward': forward,
          'backward_plot': backward,
          'label': str(item.get('label', f'запуск {len(restored) + 1}')),
          'params': str(item.get('params', '')),
          'enabled': bool(item.get('enabled', True)),
      })
    except Exception:
      continue
  return restored[-8:]


def refresh_history_tree_from_records():
  """Перерисовывает таблицу истории по списку HISTORY_RECORDS."""
  try:
    tree = globals().get('HISTORY_TREE')
    if tree is None:
      return
    for item in tree.get_children():
      tree.delete(item)

    query = ''
    tab_filter = 'Все вкладки'
    try:
      query = str(globals().get('HISTORY_SEARCH_VAR').get()).strip().lower()
      tab_filter = str(globals().get('HISTORY_TAB_FILTER_VAR').get()).strip()
    except Exception:
      pass

    for index, record in enumerate(HISTORY_RECORDS, start=1):
      record['id'] = index
      tab_title = str(record.get('tab_title', '—'))
      haystack = ' '.join(str(record.get(name, '')) for name in ('tab_title', 'title', 'method', 'elapsed', 'status', 'params')).lower()
      if tab_filter and tab_filter != 'Все вкладки' and tab_title != tab_filter:
        continue
      if query and query not in haystack:
        continue
      tree.insert(
          '',
          'end',
          iid=str(record['id']),
          tags=('has_data' if record.get('data_file') else 'missing_data',),
          values=(
              record.get('id', index),
              record.get('time', '—'),
              record.get('tab_title', '—'),
              record.get('title', '—'),
              record.get('method', '—'),
              record.get('elapsed', '—'),
              record.get('status', '—'),
              'есть' if record.get('data_file') else 'нет',
              record.get('params', '—'),
          ),
      )
  except Exception:
    pass


def save_persistent_state():
  """Сохраняет историю и сравнения на диск. Журнал расчёта не сохраняется."""
  try:
    _ensure_persistent_dirs()

    # Перед сохранением добавляем стабильный код вкладки к старым и новым записям.
    history_to_save = []
    for record in HISTORY_RECORDS:
      item = dict(record)
      item['tab_code'] = item.get('tab_code') or _tab_code_from_key(item.get('tab_key'))
      history_to_save.append(_jsonable(item))

    data = {
        'version': PERSISTENT_STATE_VERSION,
        'saved_at': datetime.now().isoformat(timespec='seconds'),
        'history_records': history_to_save,
        'compare_single_runs': [_serialize_single_compare_run(run) for run in COMPARE_SINGLE_RUNS],
        'compare_freq_runs': [_serialize_freq_compare_run(run) for run in COMPARE_FREQ_RUNS],
        'recent_calculation_files': list(RECENT_CALCULATION_FILES[:MAX_RECENT_CALCULATION_FILES]),
    }

    temp_file = PERSISTENT_STATE_FILE + '.tmp'
    with open(temp_file, 'w', encoding='utf-8') as file:
      json.dump(data, file, ensure_ascii=False, indent=2)
    os.replace(temp_file, PERSISTENT_STATE_FILE)
  except Exception:
    # Сохранение не должно ломать расчётную программу.
    pass


def load_persistent_state():
  """Загружает историю и сравнения после запуска программы."""
  try:
    if not os.path.exists(PERSISTENT_STATE_FILE):
      return

    with open(PERSISTENT_STATE_FILE, 'r', encoding='utf-8') as file:
      data = json.load(file)

    loaded_history = data.get('history_records', [])
    HISTORY_RECORDS.clear()
    for index, record in enumerate(loaded_history, start=1):
      if not isinstance(record, dict):
        continue
      item = dict(record)
      item['id'] = index
      # Перепривязываем вкладку к текущей сессии Tkinter.
      item['tab_key'] = resolve_history_tab_key(item)
      item['tab_code'] = item.get('tab_code') or _tab_code_from_key(item.get('tab_key'))
      HISTORY_RECORDS.append(item)

    COMPARE_SINGLE_RUNS.clear()
    COMPARE_SINGLE_RUNS.extend(_restore_single_compare_runs(data.get('compare_single_runs', [])))

    COMPARE_FREQ_RUNS.clear()
    COMPARE_FREQ_RUNS.extend(_restore_freq_compare_runs(data.get('compare_freq_runs', [])))

    RECENT_CALCULATION_FILES.clear()
    for path in data.get('recent_calculation_files', []):
      if isinstance(path, str) and path:
        RECENT_CALCULATION_FILES.append(path)
    del RECENT_CALCULATION_FILES[MAX_RECENT_CALCULATION_FILES:]
    refresh_recent_files_menu()

    refresh_history_tree_from_records()
  except Exception:
    # Если файл повреждён, просто начинаем с пустого состояния.
    HISTORY_RECORDS.clear()
    COMPARE_SINGLE_RUNS.clear()
    COMPARE_FREQ_RUNS.clear()
    RECENT_CALCULATION_FILES.clear()
    refresh_recent_files_menu()
    refresh_history_tree_from_records()



class CancelledByUser(Exception):
  pass


def raise_if_cancelled():
  if cancel_event.is_set():
    raise CancelledByUser('Расчёт отменён пользователем')


def report_progress(percent, message=None):
  # Поток расчёта не трогает Tkinter напрямую, а только кладёт обновление в очередь.
  # Сюда также добавляется прошедшее и оставшееся время.
  global current_progress_percent
  try:
    percent = float(percent)
    current_progress_percent = percent
    if message:
      message = add_timing_to_message(message, percent)
    progress_queue.put((percent, message))
  except Exception:
    pass


def clear_dynamic_widgets(frame):
  refresh_graph_layout_metrics()
  key = str(frame)
  hide_graph_placeholders(frame)
  for widget in dynamic_widgets.get(key, []):
    try:
      widget.destroy()
    except Exception:
      pass
  dynamic_widgets[key] = []
  # Контейнеры графиков тоже динамические: при новом расчёте очищаем
  # список Figure/Canvas/Toolbar, чтобы команды управления работали только
  # с актуальными графиками текущей вкладки.
  try:
    GRAPH_EMBEDS[key] = []
  except Exception:
    pass


def remember_dynamic_widget(frame, widget):
  dynamic_widgets.setdefault(str(frame), []).append(widget)


def finalize_figure(fig):
  # Единый аккуратный вид графиков без изменения самих расчётных данных.
  try:
    fig.patch.set_facecolor(CARD_BG)
    for ax in fig.axes:
      ax.set_facecolor(CARD_BG)
      ax.grid(True, color='#d4dbe8', linewidth=0.8, alpha=0.9)
      for spine in ax.spines.values():
        spine.set_color('#334155')
        spine.set_linewidth(0.8)
      ax.tick_params(colors=TEXT_COLOR, labelsize=9)
      ax.xaxis.label.set_color(TEXT_COLOR)
      ax.yaxis.label.set_color(TEXT_COLOR)
      ax.title.set_color(TEXT_COLOR)
    fig.tight_layout(pad=1.2)
  except Exception:
    pass
  return fig


def embed_figure(fig, frame, x=None, y=None, width=None, height=None, relx=None, rely=None):
  """Встраивает график в отдельный контейнер с панелью управления.

  Панель matplotlib даёт управление графиком:
  Home — вернуть исходный вид, Back/Forward — история масштаба,
  Pan — перемещение, Zoom — увеличение области, Save — сохранение изображения.
  """
  finalize_figure(fig)

  toolbar_height = 34

  if width is None:
    width = 900
  if height is None:
    height = 540

  holder = ttk.Frame(frame)
  if x is not None and y is not None:
    holder.place(x=x, y=y, width=width, height=height)
  else:
    holder.place(relx=relx, rely=rely, width=width, height=height)

  canvas = FigureCanvasTkAgg(fig, master=holder)
  widget = canvas.get_tk_widget()

  toolbar_frame = ttk.Frame(holder)
  toolbar_frame.place(x=0, y=0, width=width, height=toolbar_height)

  try:
    toolbar = NavigationToolbar2Tk(canvas, toolbar_frame, pack_toolbar=False)
    toolbar.update()
    toolbar.pack(side=LEFT, fill=X)
  except Exception:
    toolbar_height = 0

  try:
    widget.configure(background=CARD_BG, highlightthickness=1, highlightbackground=BORDER_COLOR)
  except Exception:
    pass

  widget.place(x=0, y=toolbar_height, width=width, height=max(120, height - toolbar_height))
  canvas.draw()

  # Запоминаем весь контейнер, чтобы при новом расчёте удалялись и график, и toolbar.
  remember_dynamic_widget(frame, holder)
  try:
    GRAPH_EMBEDS.setdefault(str(frame), []).append({
        'figure': fig,
        'canvas': canvas,
        'toolbar': locals().get('toolbar'),
        'toolbar_frame': toolbar_frame,
        'widget': widget,
        'holder': holder,
        'role': graph_role_from_geometry(frame, x, y, width, height),
    })
  except Exception:
    pass
  return canvas


def reset_graphs_for_frame(frame=None):
  """Возвращает исходный масштаб всех графиков выбранной вкладки."""
  key = str(frame) if frame is not None else get_current_ui_key()
  changed = False
  for item in GRAPH_EMBEDS.get(key, []):
    toolbar = item.get('toolbar')
    canvas = item.get('canvas')
    try:
      if toolbar is not None:
        toolbar.home()
      elif canvas is not None:
        canvas.draw_idle()
      changed = True
    except Exception:
      pass
  if not changed:
    showinfo('Графики', 'На текущей вкладке пока нет построенных графиков.')


def toggle_grid_for_frame(frame=None):
  """Включает/выключает сетку на всех графиках выбранной вкладки."""
  key = str(frame) if frame is not None else get_current_ui_key()
  embeds = GRAPH_EMBEDS.get(key, [])
  if not embeds:
    showinfo('Графики', 'На текущей вкладке пока нет построенных графиков.')
    return
  new_state = not GRAPH_GRID_ENABLED.get(key, True)
  GRAPH_GRID_ENABLED[key] = new_state
  for item in embeds:
    try:
      fig = item.get('figure')
      for ax in fig.axes:
        ax.grid(new_state, color='#d4dbe8', linewidth=0.8, alpha=0.9)
      item.get('canvas').draw_idle()
    except Exception:
      pass


def save_all_graphs_for_frame(frame=None):
  """Сохраняет все графики текущей вкладки в PNG-файлы с общим префиксом."""
  key = str(frame) if frame is not None else get_current_ui_key()
  embeds = GRAPH_EMBEDS.get(key, [])
  if not embeds:
    showinfo('Графики', 'На текущей вкладке пока нет построенных графиков.')
    return
  filename = asksaveasfilename(
      title='Сохранить все графики вкладки',
      defaultextension='.png',
      filetypes=[('PNG', '*.png'), ('Все файлы', '*.*')],
  )
  if not filename:
    return
  base, ext = os.path.splitext(filename)
  ext = ext or '.png'
  saved = 0
  for index, item in enumerate(embeds, start=1):
    try:
      item.get('figure').savefig(f'{base}_{index}{ext}', dpi=150, bbox_inches='tight')
      saved += 1
    except Exception:
      pass
  append_log(f'Сохранено графиков текущей вкладки: {saved}. Префикс: {base}_*.')
  if saved:
    showinfo('Графики', f'Сохранено графиков: {saved}\nПрефикс файлов:\n{base}_*')
  else:
    showerror('Графики', 'Не удалось сохранить графики текущей вкладки.')


def get_current_ui_key():
  """Возвращает ключ вкладки, с которой был запущен расчёт."""
  try:
    selected = notebook.select()
    if selected:
      return selected
  except Exception:
    pass
  return current_task_key or str(frame1)


def set_status(message, key=None):
  key = key or current_task_key or get_current_ui_key()
  try:
    STATUS_VARS[key].set(message)
  except Exception:
    try:
      STATUS_VARS[str(frame1)].set(message)
    except Exception:
      pass


def compact_status_message(message, key=None, max_len=180):
  if not message:
    return message
  text = str(message).strip()
  key = key or current_task_key or get_current_ui_key()
  prefixes = []
  if 'TAB_TITLES' in globals():
    title = TAB_TITLES.get(key, '')
    if title:
      prefixes.append(title + ': ')
  if 'STATUS_NAMES' in globals():
    title2 = STATUS_NAMES.get(key, '')
    if title2:
      prefixes.append(title2 + ': ')
  for prefix in prefixes:
    if text.startswith(prefix):
      text = text[len(prefix):].strip()
      break
  if len(text) > max_len:
    text = text[:max_len - 1] + '…'
  return text


def format_eta(seconds):
  try:
    seconds = int(max(0, seconds))
  except Exception:
    return ''
  if seconds < 60:
    return f'{seconds} с'
  minutes, sec = divmod(seconds, 60)
  if minutes < 60:
    return f'{minutes} мин {sec:02d} с'
  hours, minutes = divmod(minutes, 60)
  return f'{hours} ч {minutes:02d} мин'


def report_count_progress(done, total, title='Точка'):
  total = max(1, int(total))
  done = max(0, min(int(done), total))
  percent = 100.0 * done / total
  eta_text = ''
  try:
    if current_task_started_at is not None and done > 0:
      elapsed = time.perf_counter() - current_task_started_at
      remaining = elapsed * (total - done) / done
      eta_text = f' · осталось ≈ {format_eta(remaining)}'
  except Exception:
    eta_text = ''
  report_progress(percent, f'{title}: {done} из {total} · {percent:.1f}%{eta_text}')



def format_duration(seconds):
  """Форматирует длительность расчёта в удобный вид."""
  try:
    seconds = float(seconds)
  except Exception:
    return "неизвестно"

  if seconds < 1:
    return f"{seconds:.2f} с"

  total_seconds = int(round(seconds))
  minutes, sec = divmod(total_seconds, 60)
  hours, minutes = divmod(minutes, 60)

  if hours > 0:
    return f"{hours} ч {minutes:02d} мин {sec:02d} с"
  if minutes > 0:
    return f"{minutes} мин {sec:02d} с"
  return f"{sec} с"


def get_elapsed_time_text():
  """Возвращает текст с текущим временем выполнения активного расчёта."""
  try:
    if current_task_started_at is None:
      return ""
    return format_duration(time.perf_counter() - current_task_started_at)
  except Exception:
    return ""


def get_elapsed_seconds():
  try:
    if current_task_started_at is None:
      return None
    return max(0.0, time.perf_counter() - current_task_started_at)
  except Exception:
    return None


def get_task_estimate_key(key=None, title=None):
  key = key or current_task_key or get_current_ui_key()
  title = title or current_task_title or ''
  return f'{key}|{title}'


def update_task_duration_estimate(key, title, elapsed_seconds):
  """Обновляет среднюю длительность расчёта для будущей оценки ETA."""
  try:
    if elapsed_seconds is None or elapsed_seconds <= 0:
      return
    estimate_key = get_task_estimate_key(key, title)
    old_value = task_duration_estimates.get(estimate_key)
    if old_value is None:
      task_duration_estimates[estimate_key] = float(elapsed_seconds)
    else:
      # Сглаживаем оценку, чтобы единичный случайный запуск не ломал ETA.
      task_duration_estimates[estimate_key] = 0.7 * float(old_value) + 0.3 * float(elapsed_seconds)
  except Exception:
    pass


def get_eta_text(percent=None, key=None, title=None):
  """Возвращает текст оценки оставшегося времени.

  Для карт и Iapp–частоты используется процент выполнения.
  Для одиночных Numba-интегрирований, где промежуточного прогресса нет,
  после первого запуска используется среднее время прошлых запусков.
  """
  elapsed = get_elapsed_seconds()
  if elapsed is None:
    return 'рассчитывается'

  try:
    percent_value = None if percent is None else float(percent)
  except Exception:
    percent_value = None

  # Для задач с нормальным процентом выполнения это самая полезная оценка.
  if percent_value is not None and 10.0 <= percent_value < 100.0:
    remaining = elapsed * (100.0 - percent_value) / max(percent_value, 1e-9)
    return format_eta(remaining)

  # Для монолитных интегрирований используем историю предыдущих запусков.
  estimate = task_duration_estimates.get(get_task_estimate_key(key, title))
  if estimate is not None:
    remaining = max(0.0, float(estimate) - elapsed)
    return format_eta(remaining)

  # На первом запуске точную оценку для монолитного расчёта дать нельзя:
  # внутри Numba-цикла нет промежуточных callbacks.
  if percent_value is not None and 0.0 < percent_value < 10.0:
    return 'уточняется'

  return 'после первого замера'


def build_timing_suffix(percent=None, key=None, title=None):
  elapsed_text = get_elapsed_time_text()
  if not elapsed_text:
    return ''
  eta_text = get_eta_text(percent=percent, key=key, title=title)
  if eta_text:
    return f' · прошло {elapsed_text} · осталось ≈ {eta_text}'
  return f' · прошло {elapsed_text}'


def add_timing_to_message(message, percent=None):
  try:
    message = str(message)
    if 'прошло' in message or 'осталось' in message:
      return message
    suffix = build_timing_suffix(percent=percent)
    return message + suffix if suffix else message
  except Exception:
    return message


def append_log(message):
  """Пишет событие в нижний журнал. Вызывается только из GUI-потока."""
  try:
    log_widget = globals().get('LOG_TEXT')
    if log_widget is None:
      return
    timestamp = datetime.now().strftime('%H:%M:%S')
    log_widget.configure(state=NORMAL)
    log_widget.insert(END, f'[{timestamp}] {message}\n')
    log_widget.see(END)
    log_widget.configure(state=DISABLED)
  except Exception:
    pass


def clear_log():
  try:
    LOG_TEXT.configure(state=NORMAL)
    LOG_TEXT.delete('1.0', END)
    LOG_TEXT.configure(state=DISABLED)
  except Exception:
    pass



def save_log_to_file():
  """Сохраняет журнал расчёта в текстовый файл."""
  try:
    filename = asksaveasfilename(
        title='Сохранить журнал расчёта',
        defaultextension='.txt',
        filetypes=[('Текстовый файл', '*.txt'), ('Все файлы', '*.*')],
    )
    if not filename:
      return
    text = LOG_TEXT.get('1.0', END).strip()
    with open(filename, 'w', encoding='utf-8') as file:
      file.write(text + '\n')
    append_log(f'Журнал сохранён: {filename}')
  except Exception as error:
    showerror(title='Ошибка сохранения журнала', message=str(error))


