def build_params_summary_for_history(key):
  """Короткое описание параметров запуска для вкладки истории."""
  try:
    if key == str(frame1):
      return f'Iapp={float_iapp.get():.6g}; z={get_adv_int("single", "z")}; q={get_adv_positive("single", "q"):.2g}'
    if key == str(frame2):
      return f'Iapp={float_iapp_min.get():.6g}..{float_iapp_max.get():.6g}; Δ={float_iapp_delta.get():.6g}; z={get_adv_int("freq", "z")}'
    if key == str(frame3):
      return f'Iapp1={float_iapp_1.get():.6g}; Iapp2={float_iapp_2.get():.6g}; g_syn={float_gsyn.get():.6g}; E_syn={int_Esyn.get()}'
    if key == str(frame4):
      total = max(1, get_adv_int('sync_map', 'iapp2_points') * get_adv_int('sync_map', 'gsyn_points'))
      return f'карта {total} точек; E_syn={int_Esyn.get()}; workers={get_worker_count("sync_map", total)}'
    if key == str(frame5):
      return f'g_astro={float_gastro.get():.6g}; v4={float_u4.get():.6g}; E_syn={int_Esyn.get()}'
    if key == str(frame6):
      return f'Iapp1={float_iapp_1.get():.6g}; Iapp2={float_iapp_2.get():.6g}; g_syn={float_gsyn.get():.6g}; g_astro={float_gastro.get():.6g}; v4={float_u4.get():.6g}'
  except Exception as error:
    return f'параметры недоступны: {error}'
  return '—'


def build_run_snapshot_for_history(key):
  """Сохраняет значения видимых полей, чтобы запуск можно было повторить."""
  try:
    snapshot = {'method': method_name(frame=key)}
    if key == str(frame1):
      snapshot.update({'float_iapp': float(float_iapp.get())})
    elif key == str(frame2):
      snapshot.update({
          'float_iapp_min': float(float_iapp_min.get()),
          'float_iapp_delta': float(float_iapp_delta.get()),
          'float_iapp_max': float(float_iapp_max.get()),
      })
    elif key == str(frame3):
      snapshot.update({
          'float_iapp_1': float(float_iapp_1.get()),
          'float_iapp_2': float(float_iapp_2.get()),
          'float_gsyn': float(float_gsyn.get()),
          'int_Esyn': int(int_Esyn.get()),
      })
    elif key == str(frame4):
      snapshot.update({'int_Esyn': int(int_Esyn.get())})
    elif key == str(frame5):
      snapshot.update({
          'float_gastro': float(float_gastro.get()),
          'float_u4': float(float_u4.get()),
          'int_Esyn': int(int_Esyn.get()),
      })
    elif key == str(frame6):
      snapshot.update({
          'float_iapp_1': float(float_iapp_1.get()),
          'float_iapp_2': float(float_iapp_2.get()),
          'float_gsyn': float(float_gsyn.get()),
          'float_gastro': float(float_gastro.get()),
          'float_u4': float(float_u4.get()),
          'int_Esyn': int(int_Esyn.get()),
      })
    return snapshot
  except Exception:
    return {}


def apply_run_snapshot(record):
  """Возвращает видимые поля к значениям выбранного запуска из истории."""
  try:
    key = resolve_history_tab_key(record)
    snapshot = record.get('snapshot') or {}
    if 'method' in snapshot:
      method_var = METHOD_VARS.get(key)
      if method_var is not None:
        method_var.set(snapshot['method'])
    if key == str(frame1):
      if 'float_iapp' in snapshot:
        float_iapp.set(snapshot['float_iapp'])
    elif key == str(frame2):
      for name, var in [('float_iapp_min', float_iapp_min), ('float_iapp_delta', float_iapp_delta), ('float_iapp_max', float_iapp_max)]:
        if name in snapshot:
          var.set(snapshot[name])
    elif key == str(frame3):
      for name, var in [('float_iapp_1', float_iapp_1), ('float_iapp_2', float_iapp_2), ('float_gsyn', float_gsyn)]:
        if name in snapshot:
          var.set(snapshot[name])
      if 'int_Esyn' in snapshot:
        int_Esyn.set(snapshot['int_Esyn'])
    elif key == str(frame4):
      if 'int_Esyn' in snapshot:
        int_Esyn.set(snapshot['int_Esyn'])
    elif key == str(frame5):
      for name, var in [('float_gastro', float_gastro), ('float_u4', float_u4)]:
        if name in snapshot:
          var.set(snapshot[name])
      if 'int_Esyn' in snapshot:
        int_Esyn.set(snapshot['int_Esyn'])
    elif key == str(frame6):
      for name, var in [('float_iapp_1', float_iapp_1), ('float_iapp_2', float_iapp_2), ('float_gsyn', float_gsyn), ('float_gastro', float_gastro), ('float_u4', float_u4)]:
        if name in snapshot:
          var.set(snapshot[name])
      if 'int_Esyn' in snapshot:
        int_Esyn.set(snapshot['int_Esyn'])
  except Exception:
    pass


def add_history_record(key, title, elapsed_text, method_text, status='Готово'):
  """Добавляет завершённый расчёт в историю запусков."""
  try:
    record = {
        'id': len(HISTORY_RECORDS) + 1,
        'time': datetime.now().strftime('%H:%M:%S'),
        'tab_key': key,
        'tab_code': _tab_code_from_key(key),
        'tab_title': TAB_TITLES.get(key, title),
        'title': title,
        'method': method_text,
        'elapsed': elapsed_text,
        'status': status,
        'params': build_params_summary_for_history(key),
        'snapshot': build_run_snapshot_for_history(key),
    }
    save_history_record_dataset(record)
    HISTORY_RECORDS.append(record)
    save_persistent_state()
    tree = globals().get('HISTORY_TREE')
    if tree is not None:
      tree.insert(
          '',
          'end',
          iid=str(record['id']),
          values=(
              record['id'],
              record['time'],
              record['tab_title'],
              record['title'],
              record['method'],
              record['elapsed'],
              record['params'],
          ),
      )
  except Exception:
    pass


def get_selected_history_record():
  try:
    tree = globals().get('HISTORY_TREE')
    if tree is None:
      return None
    selection = tree.selection()
    if not selection:
      return None
    record_id = int(selection[0])
    for record in HISTORY_RECORDS:
      if int(record.get('id')) == record_id:
        return record
  except Exception:
    return None
  return None


def show_history_details():
  record = get_selected_history_record()
  if not record:
    showinfo('История расчётов', 'Выберите запуск в таблице истории.')
    return
  showinfo(
      'Подробности запуска',
      '\n'.join([
          f'Вкладка: {record["tab_title"]}',
          f'Расчёт: {record["title"]}',
          f'Время запуска: {record["time"]}',
          f'Метод: {record["method"]}',
          f'Длительность: {record["elapsed"]}',
          f'Статус: {record["status"]}',
          '',
          f'Параметры: {record["params"]}',
      ])
  )


def repeat_history_selected():
  record = get_selected_history_record()
  if not record:
    showinfo('История расчётов', 'Выберите запуск, который нужно повторить.')
    return
  key = resolve_history_tab_key(record)
  try:
    notebook.select(key)
    apply_run_snapshot(record)
  except Exception:
    pass
  runner = globals().get('RUN_FUNCTIONS', {}).get(key)
  if runner is None:
    showinfo('История расчётов', 'Для выбранной записи не найден обработчик повторного запуска.')
    return
  root.after(150, runner)


def clear_history_records():
  for record in list(HISTORY_RECORDS):
    delete_history_record_dataset(record)
  HISTORY_RECORDS.clear()
  tree = globals().get('HISTORY_TREE')
  if tree is not None:
    for item in tree.get_children():
      tree.delete(item)
  save_persistent_state()
  append_log('История расчётов очищена.')


def safe_min_max(values):
  try:
    arr = np.asarray(values, dtype=float)
    arr = arr[np.isfinite(arr)]
    if arr.size == 0:
      return '—', '—'
    return f'{float(np.min(arr)):.4g}', f'{float(np.max(arr)):.4g}'
  except Exception:
    return '—', '—'


def describe_esyn(value):
  try:
    value = int(value)
  except Exception:
    return str(value)
  if value == 0:
    return '0, возбуждающая'
  if value == -90:
    return '-90, тормозная'
  return str(value)


METHOD_VARS = {}
METHOD_COMBOS = {}
METHOD_LABEL_WIDGETS = {}


def create_method_selector(frame, x, y, width=255):
  key = str(frame)
  var = StringVar(value=METHOD_LABELS[1])
  METHOD_VARS[key] = var

  label = ttk.Label(frame, text='Метод:', background=CARD_BG)
