def _fmt_optional_float(value, digits=4):
  if value is None:
    return '—'
  try:
    return f'{float(value):.{digits}g}'
  except Exception:
    return '—'


def get_int_var_value(name, default=1):
  var = globals().get(name)
  if var is None:
    return int(default)
  try:
    return int(var.get())
  except Exception:
    return int(default)


