def integrate1():
  try:
    iapp_min = float_iapp_min.get()
    iapp_delta = float_iapp_delta.get()
    iapp_max = float_iapp_max.get()
    method = get_selected_method(frame2)
  except Exception:
    showerror(title="Ошибка", message="Введите корректные числовые данные")
    return

  if not (iapp_min < iapp_max and iapp_delta > 0):
    showerror(title="Ошибка", message="Введите корректные данные")
    return

  T = np.arange(iapp_min, iapp_max, iapp_delta)

  def work():
    initial_state = upload_date()
    Box, state_after_forward = direct_passage(
        T,
        method=method,
        progress_start=0,
        progress_end=50,
        initial_state=initial_state,
    )
    Cage, _ = return_passage(
        T,
        method=method,
        progress_start=50,
        progress_end=100,
        initial_state=state_after_forward,
    )
    return T, Box, Cage

  run_background(work, render_integrate1, 'Частотная характеристика')


def compute_frequency_and_state_for_iapp(i, method, state):
  """Считает одну точку Iapp–частота и возвращает частоту вместе с конечным состоянием.

  Важно: для частотной характеристики прямой/обратный проход НЕ являются
  независимыми точками. Конечное состояние предыдущего Iapp должно стать
  начальным состоянием следующего Iapp. Именно это даёт гистерезис.
  """
  vv, mm, nn, hh = state
  Box = integrate_date(
      vv,
      mm,
      nn,
      hh,
      z=get_adv_int('freq', 'z'),
      q=get_adv_positive('freq', 'q'),
      iapp=i,
      method=method,
      save_initial=False,
  )

  next_state = (
      float(Box[1, -1]),
      float(Box[2, -1]),
      float(Box[3, -1]),
      float(Box[4, -1]),
  )

  Box_for_frequency = data_cropping(Box)
  Cage = Maximum(Box_for_frequency)
  Container = Period(Cage)
  return Middle_Частота(Container), next_state


def compute_single_frequency_for_iapp(i, method, vv, mm, nn, hh):
  """Оставлено для независимых диагностических расчётов.

  Для вкладки Iapp–частота эта функция больше не используется, потому что
  независимый пересчёт каждой точки уничтожает прямой/обратный проход.
  """
  frequency, _ = compute_frequency_and_state_for_iapp(i, method, (vv, mm, nn, hh))
  return frequency


def frequency_passage(values, method=None, progress_start=0.0, progress_end=50.0, title='Проход', initial_state=None):
  """Последовательный проход по параметру Iapp с передачей состояния.

  Это исправляет ошибку stage18–stage20: там точки Iapp считались независимо
  и из-за этого прямой и обратный проходы становились одинаковыми.
  """
  total = max(1, len(values))
  result = [0.0] * len(values)
  state = upload_date() if initial_state is None else tuple(float(x) for x in initial_state)

  append_log(f'{title}: последовательный проход с сохранением конечного состояния между точками.')

  for idx, i in enumerate(values):
    raise_if_cancelled()
    local_percent = progress_start + (progress_end - progress_start) * idx / total
    report_progress(local_percent, f'{title}: {idx + 1} из {total} · Iapp={float(i):.4f}')
    result[idx], state = compute_frequency_and_state_for_iapp(float(i), method, state)

  report_progress(progress_end, f'{title} завершён')
  return result, state


def direct_passage(T, method=None, progress_start=0.0, progress_end=50.0, initial_state=None):
  values, final_state = frequency_passage(
      T,
      method=method,
      progress_start=progress_start,
      progress_end=progress_end,
      title='Прямой проход',
      initial_state=initial_state,
  )
  return values, final_state


def return_passage(T, method=None, progress_start=50.0, progress_end=100.0, initial_state=None):
  values, final_state = frequency_passage(
      T[::-1],
      method=method,
      progress_start=progress_start,
      progress_end=progress_end,
      title='Обратный проход',
      initial_state=initial_state,
  )
  return values, final_state



