def build_sync_time_map(gastro, Esyn, v4, method):
  iapp_values = np.arange(get_adv('sync_time', 'iapp2_min'), get_adv('sync_time', 'iapp2_max'), get_adv_positive('sync_time', 'iapp2_delta'))
  gsyn_values = np.arange(get_adv('sync_time', 'gsyn_min'), get_adv('sync_time', 'gsyn_max'), get_adv_positive('sync_time', 'gsyn_delta'))
  if len(iapp_values) == 0 or len(gsyn_values) == 0:
    raise ValueError('Проверьте диапазоны карты времени синхронизации: максимум должен быть больше минимума, шаг — больше нуля.')
  total = max(1, len(iapp_values) * len(gsyn_values))
  z = get_adv_int('sync_time', 'z')
  q = get_adv_positive('sync_time', 'q')
  workers = get_worker_count('sync_time', total)
  warn_if_parallel_memory_is_high('sync_time', workers)
  append_log(f'Карта времени синхронизации: точек {total}, рабочих потоков: {workers}.')
  values = np.zeros((len(iapp_values), len(gsyn_values)))

  if workers == 1:
    done = 0
    for row, iapp_2 in enumerate(iapp_values):
      for col, gsyn in enumerate(gsyn_values):
        raise_if_cancelled()
        values[row, col] = compute_sync_time_cell(float(iapp_2), float(gsyn), gastro, Esyn, v4, method, z, q)
        done += 1
        report_count_progress(done, total, 'Точка карты времени')
  else:
    completed = 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
      futures = {}
      for row, iapp_2 in enumerate(iapp_values):
        for col, gsyn in enumerate(gsyn_values):
          futures[pool.submit(compute_sync_time_cell, float(iapp_2), float(gsyn), gastro, Esyn, v4, method, z, q)] = (row, col)
      for future in as_completed(futures):
        raise_if_cancelled()
        row, col = futures[future]
        values[row, col] = future.result()
        completed += 1
        report_count_progress(completed, total, 'Точка карты времени')

  WWW = []
  for row, iapp_2 in enumerate(iapp_values):
    for col, gsyn in enumerate(gsyn_values):
      WWW.append([float(gsyn), float(iapp_2), float(values[row, col])])
  report_progress(100, 'Карта времени синхронизации готова')
  return WWW


