def get_astro_display_settings():
  """Параметры отображения астроцитарных графиков из расширенных настроек."""
  t_min = float(get_adv('astro', 't_min'))
  t_max = float(get_adv('astro', 't_max'))
  yellow_start = float(get_adv('astro', 'yellow_start'))
  yellow_end = float(get_adv('astro', 'yellow_end'))
  pink_start = float(get_adv('astro', 'pink_start'))
  pink_end = float(get_adv('astro', 'pink_end'))

  if t_max <= t_min:
    raise ValueError('В расширенных настройках астроцита t_max должен быть больше t_min')
  if yellow_end <= yellow_start:
    raise ValueError('В расширенных настройках астроцита конец жёлтой зоны должен быть больше начала')
  if pink_end <= pink_start:
    raise ValueError('В расширенных настройках астроцита конец розовой зоны должен быть больше начала')

  return {
      't_min': t_min,
      't_max': t_max,
      'yellow_start': yellow_start,
      'yellow_end': yellow_end,
      'pink_start': pink_start,
      'pink_end': pink_end,
  }


