def get_profiles_path():
  """Файл с сохранёнными профилями расширенных настроек."""
  try:
    base_dir = os.path.dirname(os.path.abspath(__file__))
  except Exception:
    base_dir = os.getcwd()
  return os.path.join(base_dir, 'neuron_astro_settings_profiles.json')


def load_settings_profiles():
  """Загружает профили расширенных настроек из JSON."""
  path = get_profiles_path()
  if not os.path.exists(path):
    return {}
  try:
    with open(path, 'r', encoding='utf-8') as file:
      data = json.load(file)
    if isinstance(data, dict):
      return data
  except Exception as error:
    try:
      append_log(f'Не удалось прочитать файл профилей настроек: {error}')
    except Exception:
      pass
  return {}


def save_settings_profiles(profiles):
  path = get_profiles_path()
  with open(path, 'w', encoding='utf-8') as file:
    json.dump(profiles, file, ensure_ascii=False, indent=2)


def normalize_profile_name(name):
  return str(name).strip()


def parse_advanced_value(name, raw_value, old_value):
  text = str(raw_value).strip().replace(',', '.')
  if text == '':
    raise ValueError(name)

  if isinstance(old_value, int):
    new_value = int(float(text))
    if new_value <= 0:
      raise ValueError(name)
    return new_value

  new_value = float(text)
  if name.endswith('_delta') or name == 'q' or name == 'plot_window' or name == 'max_plot_points':
    if new_value <= 0:
      raise ValueError(name)
  if name == 'transient' and not (0 <= new_value < 1):
    raise ValueError(name)
  return new_value


def validate_advanced_values(values):
  for min_name, max_name, delta_name in (
      ('iapp_min', 'iapp_max', 'iapp_delta'),
      ('iapp2_min', 'iapp2_max', 'iapp2_delta'),
      ('gsyn_min', 'gsyn_max', 'gsyn_delta'),
      ('gastro_min', 'gastro_max', 'gastro_delta'),
      ('v4_min', 'v4_max', 'v4_delta'),
  ):
    if min_name in values and max_name in values:
      if float(values[max_name]) < float(values[min_name]):
        raise ValueError(f'{max_name} < {min_name}')
    if delta_name in values and float(values[delta_name]) <= 0:
      raise ValueError(delta_name)

  if 't_min' in values and 't_max' in values:
    if float(values['t_max']) <= float(values['t_min']):
      raise ValueError('t_max <= t_min')

  for band_start, band_end in (
      ('yellow_start', 'yellow_end'),
      ('pink_start', 'pink_end'),
  ):
    if band_start in values and band_end in values:
      if float(values[band_end]) <= float(values[band_start]):
        raise ValueError(f'{band_end} <= {band_start}')

  if all(name in values for name in ('t_min', 't_max', 'yellow_start', 'yellow_end')):
    if float(values['yellow_start']) < float(values['t_min']) or float(values['yellow_end']) > float(values['t_max']):
      raise ValueError('Жёлтая зона должна быть внутри окна t_min..t_max')

  if all(name in values for name in ('t_min', 't_max', 'pink_start', 'pink_end')):
    if float(values['pink_start']) < float(values['t_min']) or float(values['pink_end']) > float(values['t_max']):
      raise ValueError('Розовая зона должна быть внутри окна t_min..t_max')

  if 'workers' in values:
    workers = int(values['workers'])
    if workers < 1:
      raise ValueError('workers')
    # Реальный запуск всё равно ограничивается безопасным get_worker_count().


def get_adv(section, name):
  return ADVANCED_SETTINGS[section][name]


def get_adv_int(section, name):
  value = int(round(float(get_adv(section, name))))
  if value <= 0:
    raise ValueError(f'Параметр {name} должен быть больше нуля')
  return value


def get_adv_positive(section, name, min_value=1e-12):
  value = float(get_adv(section, name))
  if value <= 0:
    raise ValueError(f'Параметр {name} должен быть больше нуля')
  return max(value, min_value)


def get_worker_count(section, total_tasks=1):
  workers = int(round(float(ADVANCED_SETTINGS.get(section, {}).get('workers', 1))))
  if workers <= 0:
    workers = 1
  cpu_count = os.cpu_count() or 1

  # Безопасный режим для ноутбука.
  # stage18 мог запускать 8 тяжёлых интеграторов одновременно, из-за чего ноутбук перегревался.
  # Теперь реальный максимум — 2 потока.
  return max(1, min(workers, 2, cpu_count, max(1, int(total_tasks))))


def estimate_map_memory_mb(z, workers, boxes=4, rows_per_box=2):
  return (float(z) + 1.0) * boxes * rows_per_box * 8.0 * max(1, workers) / (1024.0 ** 2)


def warn_if_parallel_memory_is_high(section, workers):
  try:
    z = get_adv_int(section, 'z')
    estimated = estimate_map_memory_mb(z, workers)
    if estimated > 2500:
      append_log(
          f'Предупреждение: параллельный расчёт может занять около {estimated:.0f} МБ памяти. '
          f'Если начнутся тормоза, уменьшите число потоков или z.'
      )
  except Exception:
    pass


def open_advanced_settings(section, title):
  settings = ADVANCED_SETTINGS[section]
  win = Toplevel(root)
  win.title(f'Расширенные настройки — {title}')
  win.configure(bg=APP_BG)
  win.resizable(False, False)
  win.transient(root)
  win.grab_set()

  ttk.Label(
      win,
      text='Эти параметры скрыты, чтобы не перегружать основной интерфейс.\n'
           'Для каждой вкладки можно сохранить отдельные профили настроек и потом быстро загружать их.',
      style='Muted.TLabel',
      wraplength=650,
      justify=LEFT
  ).grid(row=0, column=0, columnspan=3, sticky='w', padx=16, pady=(14, 8))

  # --- Профили настроек для текущей вкладки ---
  profile_frame = ttk.LabelFrame(win, text=f'Сохранённые настройки: {title}', style='Card.TLabelframe')
  profile_frame.grid(row=1, column=0, columnspan=3, sticky='ew', padx=16, pady=(0, 12))
  profile_frame.columnconfigure(1, weight=1)

  profile_name_var = StringVar()
  profile_select_var = StringVar()

  ttk.Label(profile_frame, text='Новый профиль:', background=CARD_BG).grid(
      row=0, column=0, sticky='w', padx=10, pady=(10, 4)
  )
  profile_name_entry = ttk.Entry(profile_frame, textvariable=profile_name_var, width=24)
  profile_name_entry.grid(row=0, column=1, sticky='ew', padx=10, pady=(10, 4))

  ttk.Label(profile_frame, text='Выбрать профиль:', background=CARD_BG).grid(
      row=1, column=0, sticky='w', padx=10, pady=4
  )
  profile_combo = ttk.Combobox(profile_frame, textvariable=profile_select_var, state='readonly', width=36)
  profile_combo.grid(row=1, column=1, sticky='ew', padx=10, pady=4)

  vars_by_name = {}

  def refresh_profile_combo(selected=None):
    profiles = load_settings_profiles()
    section_profiles = profiles.get(section, {})
    names = sorted(section_profiles.keys())
    profile_combo.configure(values=names)
    if selected in names:
      profile_select_var.set(selected)
    elif profile_select_var.get() not in names:
      profile_select_var.set(names[0] if names else '')

  def collect_form_values():
    values = {}
    for name, var in vars_by_name.items():
      values[name] = parse_advanced_value(name, var.get(), settings[name])
    validate_advanced_values(values)
    return values

  def apply_values_to_form(values):
    for name, var in vars_by_name.items():
      if name in values:
        var.set(str(values[name]))

  def apply_values_to_settings(values):
    for name, value in values.items():
      if name in settings:
        settings[name] = value

  def save_profile():
    try:
      values = collect_form_values()
      name = normalize_profile_name(profile_name_var.get()) or normalize_profile_name(profile_select_var.get())
      if not name:
        showerror(
            title='Название профиля',
            message='Введите название нового профиля или выберите существующий профиль для перезаписи.'
        )
        return

      profiles = load_settings_profiles()
      profiles.setdefault(section, {})[name] = values
      save_settings_profiles(profiles)
      refresh_profile_combo(selected=name)
      profile_name_var.set('')
      append_log(f'Сохранён профиль настроек «{name}» для вкладки «{title}».')
    except Exception:
      showerror(
          title='Ошибка сохранения профиля',
          message='Проверьте значения перед сохранением профиля.'
      )

  def load_profile():
    name = normalize_profile_name(profile_select_var.get())
    profiles = load_settings_profiles()
    section_profiles = profiles.get(section, {})
    if not name or name not in section_profiles:
      showerror(title='Профиль не выбран', message='Выберите сохранённый профиль из списка.')
      return

    try:
      values = {}
      for key, value in section_profiles[name].items():
        if key in settings:
          values[key] = parse_advanced_value(key, value, settings[key])
      validate_advanced_values(values)
      apply_values_to_form(values)
      apply_values_to_settings(values)
      append_log(f'Загружен профиль настроек «{name}» для вкладки «{title}».')
    except Exception:
      showerror(
          title='Ошибка загрузки профиля',
          message='Профиль повреждён или содержит некорректные значения.'
      )

  def delete_profile():
    name = normalize_profile_name(profile_select_var.get())
    profiles = load_settings_profiles()
    section_profiles = profiles.get(section, {})
    if not name or name not in section_profiles:
      showerror(title='Профиль не выбран', message='Выберите профиль, который нужно удалить.')
      return

    try:
      del section_profiles[name]
      if section_profiles:
        profiles[section] = section_profiles
      elif section in profiles:
        del profiles[section]
      save_settings_profiles(profiles)
      refresh_profile_combo()
      append_log(f'Удалён профиль настроек «{name}» для вкладки «{title}».')
    except Exception as error:
      showerror(title='Ошибка удаления профиля', message=str(error))

  profile_buttons = ttk.Frame(profile_frame)
  profile_buttons.grid(row=2, column=0, columnspan=2, sticky='e', padx=10, pady=(6, 10))
  ttk.Button(profile_buttons, text='Сохранить профиль', command=save_profile, style='Save.TButton').pack(side=LEFT, padx=(0, 8))
  ttk.Button(profile_buttons, text='Загрузить и применить', command=load_profile, style='Accent.TButton').pack(side=LEFT, padx=(0, 8))
  ttk.Button(profile_buttons, text='Удалить', command=delete_profile).pack(side=LEFT)

  # --- Таблица параметров ---
  params_frame = ttk.LabelFrame(win, text='Параметры текущей вкладки', style='Card.TLabelframe')
  params_frame.grid(row=2, column=0, columnspan=3, sticky='ew', padx=16, pady=(0, 12))
  params_frame.columnconfigure(1, weight=1)

  for row, (name, value) in enumerate(settings.items(), start=0):
    ttk.Label(params_frame, text=ADVANCED_LABELS.get(name, name), background=CARD_BG).grid(
        row=row, column=0, sticky='w', padx=10, pady=5
    )
    var = StringVar(value=str(value))
    vars_by_name[name] = var
    ttk.Entry(params_frame, textvariable=var, width=20).grid(
        row=row, column=1, sticky='e', padx=10, pady=5
    )

  button_frame = ttk.Frame(win)
  button_frame.grid(row=3, column=0, columnspan=3, sticky='e', padx=16, pady=(2, 16))

  def apply_settings():
    try:
      values = collect_form_values()
      apply_values_to_settings(values)
      append_log(f'Обновлены расширенные настройки: {title}.')
      win.destroy()
    except Exception:
      showerror(
          title='Ошибка настроек',
          message='Проверьте значения. Шаги должны быть больше нуля, z — положительным, transient — от 0 до 1, max должен быть больше min.'
      )

  def reset_settings():
    # Локальный сброс к тем значениям, которые сейчас активны в программе.
    for name, var in vars_by_name.items():
      var.set(str(settings[name]))

  refresh_profile_combo()

  ttk.Button(button_frame, text='Применить и закрыть', command=apply_settings, style='Accent.TButton').pack(side=RIGHT, padx=(8, 0))
  ttk.Button(button_frame, text='Закрыть', command=win.destroy).pack(side=RIGHT)
  ttk.Button(button_frame, text='Вернуть текущие', command=reset_settings).pack(side=RIGHT, padx=(0, 8))


