def create_control_card(frame, title, height=760):
    # Единая левая панель параметров. Все вкладки имеют одинаковую структуру:
    # сверху статус, слева параметры, справа графики, снизу журнал.
    card = ttk.LabelFrame(frame, text=title, style='Card.TLabelframe')
    card.place(x=SIDEBAR_X, y=SIDEBAR_Y, width=SIDEBAR_W, height=height)
    CONTROL_CARDS.append(card)
    return card


def create_graph_card(frame, title='Область графиков'):
    # Светлая карточка под графики: визуально отделяет расчётную область от панели ввода.
    card = ttk.LabelFrame(frame, text=title, style='Card.TLabelframe')
    card.place(x=GRAPH_AREA_X, y=SIDEBAR_Y, relwidth=1.0, width=-(GRAPH_AREA_X + 24), height=760)
    GRAPH_CARDS.append(card)
    return card

