def shift_static_controls(frame, dy):
    """Аккуратно смещает элементы управления внутрь карточки параметров.

    Это исправляет наложение заголовка карточки и полей ввода,
    не затрагивая верхнюю статусную панель и сами карточки.
    Динамические графики создаются позже и этой функции не касаются.
    """
    protected = set(TOP_PANELS) | set(CONTROL_CARDS)
    for child in frame.winfo_children():
        if child in protected:
            continue
        try:
            info = child.place_info()
        except Exception:
            continue
        if not info:
            continue
        try:
            y = int(float(info.get('y', 0)))
        except Exception:
            continue
        # Статусная панель заканчивается примерно на y=54, карточка начинается на y=78.
        # Все статические элементы управления переносим внутрь карточки единым блоком.
        if y < 360:
            child.place_configure(y=y + dy)


# Исправление геометрии вкладок: в stage9 часть полей начиналась слишком высоко
# и пересекалась с заголовками карточек/статусной панелью.
shift_static_controls(frame2, 58)
shift_static_controls(frame3, 58)
shift_static_controls(frame4, 40)
shift_static_controls(frame5, 62)
shift_static_controls(frame6, 58)


def _place_if_exists(widget, x, y, width=None, height=None):
    try:
        kwargs = {'x': x, 'y': y}
        if width is not None:
            kwargs['width'] = width
        if height is not None:
            kwargs['height'] = height
        widget.place_configure(**kwargs)
    except Exception:
        pass


def _place_pair(label, entry, y, label_w=120, entry_w=170):
    # label_w задаёт фактическую ширину подписи; поле ставится сразу после неё.
    # Так короткие подписи V/m/n/h, v4, Iapp_1 не получают огромный пустой отступ.
    _place_if_exists(label, 30, y, label_w, 24)
