def schedule_responsive_layout(event=None):
    try:
        if event is not None and event.widget is not root:
            return
        global RESPONSIVE_AFTER_ID
        if RESPONSIVE_AFTER_ID is not None:
            root.after_cancel(RESPONSIVE_AFTER_ID)
        RESPONSIVE_AFTER_ID = root.after(120, reflow_static_graph_layout)
    except Exception:
        pass


