def _get_single_run_frequency_for_compare(run):
    """Возвращает частотную кривую одиночного запуска.

    Сначала берёт сохранённые freq_t/freq. Если их нет, вычисляет частоту
    по сохранённому V(t), чтобы в сравнении не пропадал нижний график.
    """
    try:
        ft = np.asarray(run.get('freq_t', []), dtype=float)
        fy = np.asarray(run.get('freq', []), dtype=float)
        if ft.size > 0 and fy.size > 0:
            return ft, fy

        t = np.asarray(run.get('t', []), dtype=float)
        v = np.asarray(run.get('v', []), dtype=float)
        if t.size < 3 or v.size < 3:
            return np.array([]), np.array([])

        cage = Maximum(np.vstack([t, v]))
        cell = Частота(cage)
        ft = np.asarray(cell[0], dtype=float)
        fy = np.asarray(cell[1], dtype=float)

        # Сохраняем обратно, чтобы при следующем открытии не пересчитывать.
        run['freq_t'] = ft
        run['freq'] = fy
        return ft, fy
    except Exception:
        return np.array([]), np.array([])


def add_current_single_to_compare():
    latest = globals().get('LATEST_SINGLE_RUN')
    latest_freq = globals().get('LATEST_SINGLE_FREQ')
    if latest is None:
        showinfo('Сравнение', 'Сначала выполните расчёт на вкладке «Одиночный нейрон».')
        return
    item = {
        't': np.array(latest['t'], copy=True),
        'v': np.array(latest['v'], copy=True),
        'label': latest.get('label', f'запуск {len(COMPARE_SINGLE_RUNS) + 1}'),
        'params': latest.get('params', ''),
        'enabled': True,
    }
    if latest_freq is not None:
        item['freq_t'] = np.array(latest_freq.get('t', []), dtype=float, copy=True)
        item['freq'] = np.array(latest_freq.get('freq', []), dtype=float, copy=True)

    # Запасной вариант: если частота не была сохранена, вычисляем её из сохранённого V(t).
    # Это нужно, чтобы сравнение всегда включало не только мембранный потенциал, но и частоту.
    if len(item.get('freq_t', [])) == 0 or len(item.get('freq', [])) == 0:
        ft, fy = _get_single_run_frequency_for_compare(item)
        item['freq_t'] = ft
        item['freq'] = fy

    COMPARE_SINGLE_RUNS.append(item)
    if len(COMPARE_SINGLE_RUNS) > 8:
        del COMPARE_SINGLE_RUNS[0]
    save_persistent_state()
    append_log(f'Одиночный нейрон добавлен к сравнению. Запусков в сравнении: {len(COMPARE_SINGLE_RUNS)}.')


def show_single_comparison_window():
    if not COMPARE_SINGLE_RUNS:
        showinfo('Сравнение', 'Нет запусков одиночного нейрона для сравнения.')
        return
    enabled_runs = [(index, run) for index, run in enumerate(COMPARE_SINGLE_RUNS, start=1) if run.get('enabled', True)]
    if not enabled_runs:
        showinfo('Сравнение', 'Все одиночные запуски выключены. Включите хотя бы один запуск в менеджере сравнений.')
        return

    has_frequency = any(
        _get_single_run_frequency_for_compare(run)[0].size > 0
        for _, run in enabled_runs
    )

    if has_frequency:
        fig, (ax, ax_freq) = plt.subplots(2, 1, figsize=(10.5, 7.8), sharex=False)
    else:
        fig, ax = plt.subplots(figsize=(10, 6))
        ax_freq = None

    for index, run in enabled_runs:
        ax.plot(run['t'], run['v'], linewidth=1.2, label=f'{index}: {run["label"]}')
    ax.set_xlabel('Время, с')
    ax.set_ylabel('Мембранный потенциал V, мВ')
    ax.set_title('Сравнение запусков одиночного нейрона')
    ax.legend(loc='upper right', fontsize=8)
    ax.grid(True)

    if ax_freq is not None:
        for index, run in enabled_runs:
            ft, fy = _get_single_run_frequency_for_compare(run)
            if ft.size and fy.size:
                ax_freq.plot(ft, fy, linewidth=1.2, label=f'{index}: {run["label"]}')
        ax_freq.set_xlabel('Время, с')
        ax_freq.set_ylabel('Частота, 1/с')
        ax_freq.set_title('Сравнение частоты спайковой активности')
        ax_freq.set_ylim(0, 100)
        ax_freq.legend(loc='upper right', fontsize=8)
        ax_freq.grid(True)

    _embed_figure_in_toplevel('Сравнение одиночного нейрона и частоты', fig)


def add_current_freq_to_compare():
    latest = globals().get('LATEST_FREQ_RUN')
    if latest is None:
        showinfo('Сравнение', 'Сначала выполните расчёт на вкладке «Iapp–частота».')
        return
    item = {
        'T': np.array(latest['T'], copy=True),
        'forward': np.array(latest['forward'], copy=True),
        'backward_plot': np.array(latest['backward_plot'], copy=True),
        'label': latest.get('label', f'запуск {len(COMPARE_FREQ_RUNS) + 1}'),
        'params': latest.get('params', ''),
        'enabled': True,
    }
    COMPARE_FREQ_RUNS.append(item)
    if len(COMPARE_FREQ_RUNS) > 8:
        del COMPARE_FREQ_RUNS[0]
    save_persistent_state()
    append_log(f'Iapp–частота добавлена к сравнению. Запусков в сравнении: {len(COMPARE_FREQ_RUNS)}.')


def show_freq_comparison_window():
    if not COMPARE_FREQ_RUNS:
        showinfo('Сравнение', 'Нет частотных характеристик для сравнения.')
        return
    enabled_runs = [(index, run) for index, run in enumerate(COMPARE_FREQ_RUNS, start=1) if run.get('enabled', True)]
    if not enabled_runs:
        showinfo('Сравнение', 'Все частотные характеристики выключены. Включите хотя бы один запуск в менеджере сравнений.')
        return

    fig, ax = plt.subplots(figsize=(10, 6))
    for index, run in enabled_runs:
        ax.plot(run['T'], run['forward'], linewidth=1.4, label=f'{index} прямой: {run["label"]}')
        ax.plot(run['T'], run['backward_plot'], linestyle='--', linewidth=1.2, label=f'{index} обратный')
    ax.set_xlabel('Входной ток Iapp, отн. ед.')
    ax.set_ylabel('Средняя частота, 1/с')
    ax.set_title('Сравнение частотных характеристик')
    ax.legend(loc='upper right', fontsize=8)
    ax.grid(True)
    _embed_figure_in_toplevel('Сравнение Iapp–частота', fig)



def _comparison_short_params(run, max_len=90):
    text = str(run.get('params', '') or '')
    if len(text) > max_len:
        return text[:max_len - 1] + '…'
    return text


def _show_comparison_manager(title, runs, show_callback):
    """Окно управления сравнениями.

    Можно:
    - включить/выключить конкретный запуск;
    - удалить конкретный запуск;
    - включить все;
    - выключить все;
    - открыть окно сравнения только по включённым запускам.
    """
    if not runs:
        showinfo('Сравнение', f'Список «{title}» пуст.')
        return

    window = Toplevel(root)
    window.title(f'Управление сравнением — {title}')
    window.geometry('860x460')
    window.configure(bg=APP_BG)

    header = ttk.LabelFrame(window, text=title, style='Card.TLabelframe')
    header.pack(fill=BOTH, expand=True, padx=14, pady=14)

    info = ttk.Label(
        header,
        text='Снимите галочку, чтобы временно скрыть запуск на сравнительном графике. Нажмите «Удалить», чтобы убрать запуск из списка окончательно.',
        background=CARD_BG,
        foreground=MUTED_COLOR,
        wraplength=780,
    )
    info.pack(anchor='w', padx=12, pady=(10, 8))

    list_frame = ttk.Frame(header, style='Card.TFrame')
    list_frame.pack(fill=BOTH, expand=True, padx=12, pady=(0, 10))

    canvas = Canvas(list_frame, background=CARD_BG, highlightthickness=0)
    scrollbar = ttk.Scrollbar(list_frame, orient=VERTICAL, command=canvas.yview)
    rows_frame = ttk.Frame(canvas, style='Card.TFrame')

    rows_frame.bind(
        '<Configure>',
        lambda event: canvas.configure(scrollregion=canvas.bbox('all'))
    )
    canvas.create_window((0, 0), window=rows_frame, anchor='nw')
    canvas.configure(yscrollcommand=scrollbar.set)

    canvas.pack(side=LEFT, fill=BOTH, expand=True)
    scrollbar.pack(side=RIGHT, fill=Y)

    def refresh_rows():
        for child in rows_frame.winfo_children():
            child.destroy()

        if not runs:
            ttk.Label(
                rows_frame,
                text='Список пуст.',
                background=CARD_BG,
                foreground=MUTED_COLOR,
            ).grid(row=0, column=0, sticky='w', padx=8, pady=8)
            return

        ttk.Label(rows_frame, text='Вкл.', background=CARD_BG, foreground=MUTED_COLOR).grid(row=0, column=0, sticky='w', padx=(6, 10), pady=4)
        ttk.Label(rows_frame, text='№', background=CARD_BG, foreground=MUTED_COLOR).grid(row=0, column=1, sticky='w', padx=(0, 8), pady=4)
        ttk.Label(rows_frame, text='Название / параметры', background=CARD_BG, foreground=MUTED_COLOR).grid(row=0, column=2, sticky='w', padx=(0, 8), pady=4)
        ttk.Label(rows_frame, text='Действие', background=CARD_BG, foreground=MUTED_COLOR).grid(row=0, column=3, sticky='w', padx=(0, 8), pady=4)

        for idx, run in enumerate(runs):
            enabled_var = IntVar(value=1 if run.get('enabled', True) else 0)

            def set_enabled(index=idx, var=enabled_var):
                if 0 <= index < len(runs):
                    runs[index]['enabled'] = bool(var.get())
                    save_persistent_state()
                    append_log(
                        f'Сравнение «{title}»: запуск {index + 1} '
                        f'{"включён" if runs[index]["enabled"] else "выключен"}.'
                    )

            def delete_run(index=idx):
                if 0 <= index < len(runs):
                    deleted_label = runs[index].get('label', f'запуск {index + 1}')
                    del runs[index]
                    save_persistent_state()
                    append_log(f'Сравнение «{title}»: удалён запуск {index + 1}: {deleted_label}.')
                    refresh_rows()

            row = idx + 1
            ttk.Checkbutton(rows_frame, variable=enabled_var, command=set_enabled).grid(row=row, column=0, sticky='w', padx=(6, 10), pady=3)
            ttk.Label(rows_frame, text=str(idx + 1), background=CARD_BG).grid(row=row, column=1, sticky='w', padx=(0, 8), pady=3)

            label_text = f'{run.get("label", f"запуск {idx + 1}")}'
            params_text = _comparison_short_params(run)
            if params_text:
                label_text += f'    |    {params_text}'

            ttk.Label(
                rows_frame,
                text=label_text,
                background=CARD_BG,
                wraplength=560,
                justify=LEFT,
            ).grid(row=row, column=2, sticky='w', padx=(0, 8), pady=3)

            ttk.Button(
                rows_frame,
                text='Удалить',
                command=delete_run,
                style='Danger.TButton',
            ).grid(row=row, column=3, sticky='w', padx=(0, 8), pady=3)

    def enable_all():
        for run in runs:
            run['enabled'] = True
        save_persistent_state()
        append_log(f'Сравнение «{title}»: включены все запуски.')
        refresh_rows()

    def disable_all():
        for run in runs:
            run['enabled'] = False
        save_persistent_state()
        append_log(f'Сравнение «{title}»: выключены все запуски.')
        refresh_rows()

    buttons = ttk.Frame(header, style='Card.TFrame')
    buttons.pack(fill=X, padx=12, pady=(0, 12))
    ttk.Button(buttons, text='Показать сравнение', command=show_callback, style='Accent.TButton').pack(side=LEFT, padx=(0, 8))
    ttk.Button(buttons, text='Включить все', command=enable_all).pack(side=LEFT, padx=(0, 8))
    ttk.Button(buttons, text='Выключить все', command=disable_all).pack(side=LEFT, padx=(0, 8))
    ttk.Button(buttons, text='Закрыть', command=window.destroy, style='Save.TButton').pack(side=RIGHT)

    refresh_rows()


def manage_single_comparisons():
    _show_comparison_manager('Одиночный нейрон', COMPARE_SINGLE_RUNS, show_single_comparison_window)


def manage_freq_comparisons():
    _show_comparison_manager('Iapp–частота', COMPARE_FREQ_RUNS, show_freq_comparison_window)


def clear_comparisons():
    COMPARE_SINGLE_RUNS.clear()
    COMPARE_FREQ_RUNS.clear()
    save_persistent_state()
    append_log('Сравнения очищены.')
    showinfo('Сравнение', 'Списки сравнений очищены.')


