def on_app_close():
    save_persistent_state()
    cancel_event.set()
    try:
        append_log('Закрытие приложения.')
    except Exception:
        pass

    # страховка: если какие-то worker-thread'ы или библиотеки мешают выйти,
    # процесс будет завершён принудительно чуть позже.
    try:
        killer = threading.Timer(1.0, lambda: os._exit(0))
        killer.daemon = True
        killer.start()
    except Exception:
        killer = None

    try:
        executor.shutdown(wait=False, cancel_futures=True)
    except TypeError:
        try:
            executor.shutdown(wait=False)
        except Exception:
            pass
    except Exception:
        pass

    try:
        plt.close('all')
    except Exception:
        pass

    try:
        root.quit()
    except Exception:
        pass

    try:
        root.destroy()
    except Exception:
        pass


# ---------------------------------------------------------------------------
# Просмотр сохранённых результатов из истории прямо на соответствующей вкладке
# ---------------------------------------------------------------------------
# пользователь не видел результат в основном интерфейсе, а старые вкладки оставались
# пустыми. Ниже переопределяется show_loaded_history_dataset: теперь сохранённый
# результат поднимается из .npz, выбирается нужная вкладка и графики строятся
# прямо в рабочей области вкладки. Журнал при этом не восстанавливается специально:
# он по-прежнему начинается заново при каждом запуске приложения.

def _history_dataset_array(dataset, name):
  """Безопасно возвращает численный numpy-массив из сохранённого результата."""
  try:
    if dataset is None or name not in dataset:
      return np.asarray([], dtype=float)
    value = dataset.get(name)
    arr = np.asarray(value, dtype=float)
    return arr
  except Exception:
    return np.asarray([], dtype=float)


def _history_dataset_text(dataset, name, default=''):
  try:
    value = dataset.get(name, default)
    if isinstance(value, np.ndarray):
      if value.shape == ():
        return str(value.item())
      return str(value)
    return str(value)
  except Exception:
    return default


def _history_dataset_scalar(dataset, name, default=None):
  try:
    if name not in dataset:
      return default
    arr = np.asarray(dataset.get(name))
    if arr.size == 0:
      return default
    return float(arr.reshape(-1)[0])
  except Exception:
    return default


def _history_record_display_name(record, dataset=None):
  try:
    label = ''
    if dataset is not None:
      meta = dataset.get('meta') or {}
      label = str(meta.get('label') or '').strip()
    if not label:
      label = str(record.get('params') or record.get('title') or 'сохранённый запуск')
    return label
  except Exception:
    return 'сохранённый запуск'


def _select_history_tab(tab_frame):
  try:
    notebook.select(tab_frame)
  except Exception:
    pass


def _prepare_history_tab(tab_frame, status_text='Открыт результат из истории'):
  try:
    clear_dynamic_widgets(tab_frame)
  except Exception:
    pass
  try:
    set_busy(False, status_text, key=str(tab_frame))
    set_progress(0, status_text, key=str(tab_frame))
  except Exception:
    try:
      set_status(status_text, key=str(tab_frame))
    except Exception:
      pass


def _history_empty_figure(title='Нет сохранённых численных данных'):
  fig, ax = plt.subplots(figsize=(8.0, 3.2))
  ax.text(0.5, 0.5, title, ha='center', va='center', transform=ax.transAxes)
  ax.set_axis_off()
  return fig


def _history_update_info(tab_frame, title, record, dataset, extra_lines=None):
  key = str(tab_frame)
  source_mode = str(record.get('source_mode', '') or '')
  if source_mode == 'current':
    source_line = 'Источник: последний расчёт текущей вкладки'
    info_status = 'Последний расчёт'
  else:
    source_line = f"Источник: история, запуск №{record.get('id', '-')}"
    info_status = 'Открыт из истории'
  lines = [
      source_line,
      f"Время запуска: {record.get('time', '-')}",
      f"Метод: {record.get('method', '-')}",
      f"Длительность расчёта: {record.get('elapsed', '-')}",
  ]
  params = str(record.get('params', '')).strip()
  if params:
    lines.append(f"Параметры: {params}")
  if extra_lines:
    lines.extend(extra_lines)
  try:
    data_file = str(record.get('data_file', '') or '')
    if source_mode == 'current':
      update_source_badge(key, f'Последний расчёт: {title}', mode='current')
    elif data_file and (os.path.isabs(data_file) or record.get('id') == 'файл'):
      update_source_badge(key, f'Открыт файл: {os.path.basename(data_file)}', mode='file')
    else:
      update_source_badge(key, f'Открыт из истории: запуск №{record.get("id", "-")}', mode='history')
    update_calculation_info(key, title, lines, status=info_status)
  except Exception:
    pass


def _restore_history_single(record, dataset):
  _select_history_tab(frame1)
  _prepare_history_tab(frame1)

  t = _history_dataset_array(dataset, 't')
  v = _history_dataset_array(dataset, 'v')
  m_arr = _history_dataset_array(dataset, 'm')
  n_arr = _history_dataset_array(dataset, 'n')
  h_arr = _history_dataset_array(dataset, 'h')
  freq_t = _history_dataset_array(dataset, 'freq_t')
  freq = _history_dataset_array(dataset, 'freq')

  figures = calculation_plotting.create_single_figures(dataset)
  embed_figure(figures.get('vt') or calculation_plotting.empty_figure(), frame1,
               x=GRAPH_LEFT_X, y=GRAPH_TOP_Y, width=GRAPH_W, height=GRAPH_H)
  embed_figure(figures.get('phase') or calculation_plotting.empty_figure(), frame1,
               x=GRAPH_RIGHT_X, y=GRAPH_TOP_Y, width=GRAPH_W, height=GRAPH_H)
  embed_figure(figures.get('gates') or calculation_plotting.empty_figure(), frame1,
               x=GRAPH_LEFT_X, y=GRAPH_BOTTOM_Y, width=GRAPH_W, height=GRAPH_H)
  embed_figure(figures.get('freq') or calculation_plotting.empty_figure(), frame1,
               x=GRAPH_RIGHT_X, y=GRAPH_BOTTOM_Y, width=GRAPH_W, height=GRAPH_H)

  try:
    if len(v):
      label_param5.config(text=f"V: {float(v[-1]):.6f}")
    if len(m_arr):
      label_param6.config(text=f"m: {float(m_arr[-1]):.6f}")
    if len(n_arr):
      label_param7.config(text=f"n: {float(n_arr[-1]):.6f}")
    if len(h_arr):
      label_param8.config(text=f"h: {float(h_arr[-1]):.6f}")
  except Exception:
    pass

  _history_update_info(
      frame1,
      'Одиночный нейрон',
      record,
      dataset,
      [f'Точек V(t): {len(t)}', f'Точек частоты: {len(freq_t)}'],
  )
  append_log(f"История: открыт результат на вкладке «Одиночный нейрон», запуск №{record.get('id', '-')}.")
  return True


