def _restore_history_astro(record, dataset):
  _select_history_tab(frame6)
  _prepare_history_tab(frame6)

  t_ca = _history_dataset_array(dataset, 't_ca')
  ca = _history_dataset_array(dataset, 'ca')
  freq_t1 = _history_dataset_array(dataset, 'freq_t1')
  freq1 = _history_dataset_array(dataset, 'freq1')
  freq_t2 = _history_dataset_array(dataset, 'freq_t2')
  freq2 = _history_dataset_array(dataset, 'freq2')

  try:
    display_settings = get_astro_display_settings()
  except Exception:
    display_settings = {
        't_min': 22,
        't_max': 40,
        'yellow_start': 28,
        'yellow_end': 32.6,
        'pink_start': 32.6,
        'pink_end': 36.7,
    }
  display_settings = {
      't_min': _history_dataset_scalar(dataset, 'display_t_min', display_settings['t_min']),
      't_max': _history_dataset_scalar(dataset, 'display_t_max', display_settings['t_max']),
      'yellow_start': _history_dataset_scalar(dataset, 'display_yellow_start', display_settings['yellow_start']),
      'yellow_end': _history_dataset_scalar(dataset, 'display_yellow_end', display_settings['yellow_end']),
      'pink_start': _history_dataset_scalar(dataset, 'display_pink_start', display_settings['pink_start']),
      'pink_end': _history_dataset_scalar(dataset, 'display_pink_end', display_settings['pink_end']),
  }

  fig1, fig2 = calculation_plotting.create_astro_figures(dataset, display_settings)
  embed_figure(fig1, frame6, x=WIDE_GRAPH_X, y=GRAPH_TOP_Y, width=WIDE_GRAPH_W, height=WIDE_GRAPH_H)
  embed_figure(fig2, frame6, x=WIDE_GRAPH_X, y=GRAPH_BOTTOM_Y, width=WIDE_GRAPH_W, height=WIDE_GRAPH_H)

  _history_update_info(
      frame6,
      'Астроцитарная динамика',
      record,
      dataset,
      [f'Точек Ca(t): {len(t_ca)}', f'Точек частоты нейрона 1: {len(freq_t1)}; нейрона 2: {len(freq_t2)}'],
  )
  append_log(f"История: открыт результат на вкладке «Астроцит», запуск №{record.get('id', '-')}.")
  return True


DATASET_RENDERERS = {
    'single': _restore_history_single,
    'freq': _restore_history_freq,
    'pair': _restore_history_pair,
    'sync_map': _restore_history_sync_map,
    'sync_time': _restore_history_sync_time,
    'astro': _restore_history_astro,
}


def render_dataset_graphs(record, dataset):
  """Единый вход для построения графиков из сохранённого dataset."""
  kind = str(dataset.get('kind') or (dataset.get('meta') or {}).get('kind') or record.get('data_kind') or '').strip()
  renderer = DATASET_RENDERERS.get(kind)
  if renderer is None:
    showinfo('История', 'Не удалось определить тип сохранённого результата.')
    return False
  return renderer(record, dataset)


def show_current_run_dataset_for_frame(frame=None):
  """Возвращает вкладку к последнему рассчитанному результату после просмотра файла/истории."""
  try:
    target_frame = frame if frame is not None else notebook.nametowidget(notebook.select())
    key = str(target_frame)
    dataset = get_current_run_dataset(key)
    if not dataset:
      showinfo('Последний расчёт', 'На этой вкладке пока нет завершённого расчёта.')
      return
    kind = str(dataset.get('kind', '') or '').strip()
    record = _make_record_for_dataset(kind=kind, meta={}, path='')
    record['id'] = 'последний'
    record['source_mode'] = 'current'
    render_dataset_graphs(record, dataset)
  except Exception as exc:
    showerror('Последний расчёт', f'Не удалось вернуть последний расчёт:\n\n{exc}')


def show_loaded_history_dataset(record, dataset):
  """Показывает выбранный сохранённый результат из истории на родной вкладке."""
  if dataset is None:
    showinfo(
        'История',
        'Для выбранного запуска нет сохранённых численных данных.\n\n'
        'Это возможно для записей, созданных до появления постоянного хранения результатов. '
        'Повторите запуск из истории — новый результат уже будет открываться и экспортироваться.',
    )
    return

  try:
    render_dataset_graphs(record, dataset)
  except Exception as exc:
    showerror('История', f'Не удалось открыть результат из истории:\\n\\n{exc}')

append_log('Приложение запущено.')
root.protocol("WM_DELETE_WINDOW", on_app_close)
try:
    root.mainloop()
finally:
    cancel_event.set()
    try:
        executor.shutdown(wait=False, cancel_futures=True)
    except TypeError:
        try:
            executor.shutdown(wait=False)
        except Exception:
            pass
    except Exception:
        pass
    try:
        plt.close('all')
    except Exception:
        pass
